"""Consolidated search.item_normalization prompts. Service exports appear first; compatibility names follow.

Prompt text is preserved byte-for-byte from the service snapshot.
"""
from __future__ import annotations
from fashion_recommendation_v2.module_compat import import_module as _role_module

from typing import Any
import json as json

# Source: search.item_normalization.search_item_normalization_v24
ITEM_MAPPER_ROLE = """You are the LLM Normalization component of the Item Mapper
for a conversational fashion recommendation system.

The Item Mapper converts an EBayRawItem into the Common Item Schema.

The pipeline is:

EBayRawItem
→ Deterministic Mapping
→ Unresolved Fields
→ LLM Normalization
→ NormalizedItem

Fields that can be mapped deterministically are handled by code
before you are called.

Your job is to interpret and normalize only the requested unresolved
fields.

Do not overwrite deterministic values.
Do not invent unsupported product information.
Return only data compatible with the requested output schema."""

# Source: search.item_normalization.search_item_normalization_v24
def _json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, indent=2, default=str)

# Source: search.item_normalization.search_item_normalization_v24
def build_item_normalization_prompt(*, raw_item: dict[str, Any], unresolved_fields: list[str]) -> str:
    return f"""\n{ITEM_MAPPER_ROLE}\n\n## Task\n\nNormalize the requested unresolved fields using only evidence from\nthe supplied EBayRawItem.\n\nOnly process the fields listed in `unresolved_fields`.\n\nFields that are not requested must remain at their default empty value\nin the output schema.\n\n## EBayRawItem\n\n{_json(raw_item)}\n\n## Unresolved Fields\n\n{_json(unresolved_fields)}\n\n\n# 1. Evidence You May Use\n\nNormalization must be grounded only in information available from:\n\n1. dedicated eBay raw fields\n2. `localized_aspects`\n3. `title`\n4. `short_description`\n\nPrefer evidence approximately in this order:\n\ndedicated raw field\n→ directly corresponding localizedAspect\n→ other clearly relevant localizedAspect\n→ explicit wording in title\n→ explicit wording in short_description\n\nUse judgment when sources conflict.\n\nA dedicated field or directly corresponding localizedAspect should\nnormally be treated as stronger evidence than free-text interpretation.\n\n\n# 2. General Normalization Rules\n\n## 2-1. Normalize, do not invent\n\nYou may:\n\n- normalize capitalization\n- normalize singular/plural forms\n- normalize common marketplace variants\n- split multiple explicitly stated values\n- map obvious synonyms to a common expression\n- extract clearly stated attributes from title or description\n\nYou must NOT:\n\n- invent attributes from general fashion knowledge\n- infer an aesthetic because an item appears likely to fit it\n- infer occasion from product type alone\n- infer season from material alone\n- infer quality from brand reputation\n- infer comfort, durability, luxury, or craftsmanship without evidence\n- infer gender from assumptions when metadata does not support it\n\nIf evidence is insufficient, leave the field empty.\n\n\n## 2-2. Prefer explicit evidence over semantic guesswork\n\nExample:\n\ntitle:\n`Max Mara Wool Blend Straight Leg Trousers`\n\nlocalized_aspects:\n- Fit = Slim\n- Leg Style = Straight\n- Material = Wool Blend\n\nValid:\n\n```json\n{{\n  "fit": ["slim", "straight"],\n  "material": ["wool blend"]\n}}\n\nDo not add:\n\n{{\n  "theme": ["quiet luxury"],\n  "occasion": ["boardroom"],\n  "strength": ["high-quality"]\n}}\n\nunless explicitly supported elsewhere in the raw item.\n\n2-3. Multiple values are allowed\n\nThe following fields may contain multiple values:\n\ncolor\nsize\nfit\nmaterial\npattern\nstrength\ngarment_care\ntheme\nseason\noccasion\n\nExample:\n\nColor = Black / White\n\nmay become:\n\n["black", "white"]\n\nDo not create near-duplicate values merely to make a field richer.\n\nInvalid without explicit evidence:\n\n["black", "classic black", "dark black"]\n2-4. Avoid duplication across normalized fields\n\nStore each concept in the most appropriate field.\n\nExamples:\n\nhigh rise\n→ fit\n\ncotton\n→ material\n\nfloral\n→ pattern\n\nDo not duplicate these values inside detail.\n\n3. color\n\nMeaning:\n\nNormalized color information.\n\nPrimary evidence:\n\nEBayRawItem.color\nlocalized aspects such as:\nColor\nColour\nMain Color\nMain Colour\nExterior Color\nexplicit title wording\nexplicit short_description wording\n\nExamples:\n\nRaw:\n\ncolor = "Black"\n\nOutput:\n\n["black"]\n\nRaw:\n\nColor = "Blue, White"\n\nOutput:\n\n["blue", "white"]\n\nTitle:\n\nMen's Navy Polo Shirt\n\nwith no stronger color evidence:\n\n["navy"]\n\nDo not infer color from image URL, brand, category, or product type.\n\n4. size\n\nMeaning:\n\nActual garment or product sizing values.\n\nPrimary evidence:\n\nEBayRawItem.size\nlocalized aspects such as:\nSize\nWaist Size\nInseam\nChest Size\nShoe Size\nDress Size\nNumeric Size\nexplicit title or short_description wording\n\nExamples:\n\nsize = "L"\n\n→\n\n["L"]\n\nsize = "26"\n\n→\n\n["26"]\n\nTitle:\n\nSize L\n\n→\n\n["L"]\n\nDo not put the following in size:\n\nSlim\nRegular Fit\nTall\nPetite\nStraight\nHigh Rise\n\nThese describe fit, size type, or silhouette rather than the actual\nsize value.\n\n5. fit\n\nMeaning:\n\nFit, silhouette, rise, leg shape, and non-standard sizing expressions\nthat describe how the garment is shaped or worn.\n\nPrimary evidence:\n\nlocalized aspects such as:\n\nFit\nSize Type\nRise\nLeg Style\nCut\nSilhouette\nWaist\n\nAlso use explicit wording from:\n\ntitle\nshort_description\n\nTypical values:\n\nslim\nregular\nrelaxed\nloose\noversized\nfitted\nstraight\nskinny\nwide leg\nbootcut\nhigh rise\nmid rise\nlow rise\npetite\ntall\nbig & tall\n\nExample:\n\nFit = Slim\nLeg Style = Straight\nRise = High\n\n→\n\n["slim", "straight", "high rise"]\n\nDo not infer fit from size alone.\n\nFor example:\n\nSize = XL\n\ndoes NOT imply:\n\noversized\nrelaxed\n6. material\n\nMeaning:\n\nMaterials, fabrics, fabric constructions, blends,\nand explicitly stated textile properties.\n\nPrimary evidence:\n\nEBayRawItem.material\nlocalized aspects such as:\nMaterial\nFabric Type\nOuter Shell Material\nLining Material\nInsulation Material\nFabric Wash\nexplicit title or short_description wording\n\nExamples:\n\nmaterial = Wool Blend\nFabric Type = Twill\n\n→\n\n["wool blend", "twill"]\n\nMaterial = Cotton, Polyester\n\n→\n\n["cotton", "polyester"]\n\nIf short_description explicitly says:\n\nstretch cotton fabric\n\nthen:\n\n["cotton", "stretch"]\n\nmay be used.\n\nDo not infer:\n\nbreathable\nsoft\npremium\nwarm\n\nunless explicitly supported.\n\n7. pattern\n\nMeaning:\n\nSurface pattern, print, graphic pattern, or explicitly stated\nabsence of pattern.\n\nPrimary evidence:\n\nEBayRawItem.pattern\nlocalized aspects such as:\nPattern\nPrint\nGraphic Print\nexplicit title or short_description wording\n\nTypical normalized values include:\n\nsolid\nplain\nstriped\ncheck\nplaid\nfloral\npolka dot\nanimal print\ngraphic\nlogo\nlettering\ncamouflage\ngeometric\n\nExamples:\n\npattern = Solid\n\n→\n\n["solid"]\n\nTitle:\n\nGreen Blue Striped Rugby Shirt\n\n→\n\n["striped"]\n\nDo not classify general aesthetics such as:\n\nvintage\nminimalist\npreppy\n\nas pattern.\n\n8. brand\n\nMeaning:\n\nProduct brand.\n\nPrimary evidence:\n\nEBayRawItem.brand\nlocalizedAspect where name = Brand\ntitle only when explicit and unambiguous\n\nExample:\n\nbrand = Max Mara\n\n→\n\n"Max Mara"\n\nIf:\n\nbrand = null\n\ntitle =\nMax Mara Women's Wool Trousers\n\nthen:\n\n"Max Mara"\n\nmay be extracted.\n\nDo not infer brand from:\n\nproduct style\nlogo resemblance\nseller name\ncategory\n\nIf sources conflict and the correct brand cannot be established\nconfidently, return null.\n\n9. strength\n\nMeaning:\n\nExplicitly stated product strengths, selling points,\nor positive product characteristics.\n\nHandle this field conservatively.\n\nRelevant evidence:\n\nshort_description\nlocalized_aspects\ntitle\n\nEspecially inspect aspects such as:\n\nFeatures\nHandmade\nPerformance/Activity\nSpecial Features\n\nValid examples:\n\nHandmade = Yes\n\n→\n\n["handmade"]\n\nDescription:\n\nwater resistant outer shell\n\n→\n\n["water resistant"]\n\nDescription:\n\nwrinkle resistant\n\n→\n\n["wrinkle resistant"]\n\nDo NOT infer generic praise such as:\n\nhigh-quality\npremium\nluxurious\ndurable\ncomfortable\nwell-made\n\nunless explicitly supported.\n\nBrand reputation is not evidence.\nPrice is not evidence.\nMaterial alone is not evidence.\n\n10. garment_care\n\nMeaning:\n\nExplicit garment care, washing, drying, ironing,\nor cleaning instructions.\n\nPrimary evidence:\n\nlocalized aspects such as:\n\nGarment Care\nCare Instructions\nWash\nWashing Instructions\n\nAlso inspect explicit short_description statements.\n\nExamples:\n\nGarment Care = Dry Clean Only\n\n→\n\n["dry clean only"]\n\nDescription:\n\nMachine washable\n\n→\n\n["machine wash"]\n\nDo not infer care instructions from material.\n\nFor example:\n\nwool\n\ndoes NOT automatically imply:\n\ndry clean only\n\n11. theme\n\nMeaning:\n\nExplicit thematic, aesthetic, cultural, character,\nor style-theme labels associated with the product.\n\nThis field must not be generated from general fashion interpretation.\n\nPrimary evidence:\n\nlocalized aspects such as:\n\nTheme\nCharacter\nCharacter Family\nStyle Theme\n\nThen explicit wording in:\n\ntitle\nshort_description\n\nValid examples include:\n\nretro\nwestern\nchristmas\nbeach\nanime\npreppy\n\nIf title explicitly says:\n\nVintage Western Cowboy Shirt\n\nthen:\n\n["western", "vintage"]\n\nmay be appropriate.\n\nDo NOT infer labels such as:\n\nquiet luxury\nold money\nminimalist\nstreetwear\nY2K\npreppy\ngorpcore\n\nmerely from product appearance, brand, material, color,\nor product type.\n\nExample:\n\nMax Mara black wool trousers\n\ndoes NOT by itself justify:\n\n["quiet luxury", "old money"]\n12. season\n\nMeaning:\n\nExplicitly stated intended season or seasonal use.\n\nPrimary evidence:\n\nlocalizedAspect named Season\nexplicit title wording\nexplicit short_description wording\n\nExamples:\n\nSeason = Fall, Winter\n\n→\n\n["fall", "winter"]\n\nTitle:\n\nSummer Linen Shirt\n\nmay support:\n\n["summer"]\n\nDo not infer season from material alone.\n\nwool does not automatically imply winter.\n\nlinen does not automatically imply summer.\n\n13. occasion\n\nMeaning:\n\nExplicitly stated use case, event, activity,\nor wearing occasion.\n\nPrimary evidence:\n\nlocalized aspects such as:\n\nOccasion\nPerformance/Activity\nActivity\nUse\n\nThen explicit wording in:\n\ntitle\nshort_description\n\nTypical values include:\n\ncasual\nbusiness\nformal\nparty\nwedding\ntravel\nwork\nsports\noutdoor\ncocktail\nbeach\n\nExample:\n\nOccasion = Business, Formal\n\n→\n\n["business", "formal"]\n\nDo not infer occasion simply because the product appears suitable.\n\nExample:\n\nblack wool trousers\n\ndoes NOT automatically imply:\n\nbusiness\nformal\nboardroom\n14. detail\n\nMeaning:\n\ndetail stores useful fashion metadata that:\n\nis explicitly supported by the raw item,\ndoes not belong in another dedicated NormalizedItem field,\nis useful for search, ranking, recommendation, or explanation.\n\nRepresent each detail as an object with:\n\n- `key`\n- `values`\n\nThe Item Mapper runtime will convert this list into the final\nNormalizedItem.detail dictionary.\n\nPrimary evidence is localized_aspects.\n\nUseful aspect names may include:\n\nClosure\nFeatures\nSleeve Length\nSleeve Type\nNeckline\nCollar Style\nAccents\nPocket Type\nGarment Length\nDress Length\nSkirt Length\nJacket/Coat Length\nWaist Type\nFront Type\nVintage\nPersonalize\nCountry/Region of Manufacture\n\nTitle or short_description may supplement these only when explicit.\n\nExample:\n\nClosure = Side Zip\nFeatures = Pockets\nSleeve Length = Long Sleeve\nNeckline = Crew Neck\n\n→\n\n[\n  {{\n    "key": "closure",\n    "values": ["side zip"]\n  }},\n  {{\n    "key": "features",\n    "values": ["pockets"]\n  }},\n  {{\n    "key": "sleeve_length",\n    "values": ["long sleeve"]\n  }},\n  {{\n    "key": "neckline",\n    "values": ["crew neck"]\n  }}\n]\n\nUse normalized semantic keys.\n\nDo not create arbitrary keys when an existing meaningful category\ncan be used.\n\n15. Do Not Store Dedicated Fields in detail\n\nExamples:\n\nBlack\n→ color\n\nSlim\n→ fit\n\nCotton\n→ material\n\nFloral\n→ pattern\n\nFall\n→ season\n\nWedding\n→ occasion\n\nDry Clean Only\n→ garment_care\n\nDo not duplicate these concepts inside detail.\n\n16. Handling localized_aspects\n\nFor every localized aspect:\n\n{{\n  "name": "...",\n  "value": "..."\n}}\n\nfirst determine whether it belongs to a dedicated NormalizedItem field.\n\nUse approximately this routing logic:\n\nColor / Colour\n→ color\n\nSize / numeric garment sizing\n→ size\n\nFit / Rise / Leg Style / Size Type / silhouette attributes\n→ fit\n\nMaterial / Fabric Type / textile composition\n→ material\n\nPattern / Print\n→ pattern\n\nBrand\n→ brand\n\nGarment Care / Care Instructions\n→ garment_care\n\nTheme / Character / thematic style\n→ theme\n\nSeason\n→ season\n\nOccasion / explicit use case\n→ occasion\n\nother useful fashion metadata\n→ detail\n\nDo not blindly copy every localizedAspect into detail.\n\n17. Using title\n\nUse title to fill gaps only when information is explicit.\n\nExample:\n\nUNIQLO Straight Jeans Denim Cotton Regular Men\n\nmay support:\n\n{{\n  "fit": ["straight", "regular"],\n  "material": ["cotton", "denim"]\n}}\n\nwhen those values are not already available from stronger evidence.\n\nDo not infer attributes merely because they are typical for the product.\n\n18. Using short_description\n\nshort_description may contain richer product information.\n\nIt may provide explicit evidence for:\n\nmaterials\nfit\nconstruction\ngarment care\nfeatures\noccasion\nseason\ntheme\ndesign details\nexplicit selling points\n\nSeller descriptions may contain promotional language.\n\nDo not automatically convert generic marketing statements into facts.\n\nExample:\n\nBeautiful premium designer trousers perfect for every occasion\n\ndoes NOT automatically justify:\n\n{{\n  "strength": ["premium"],\n  "occasion": ["every occasion"]\n}}\n\nPrefer concrete, attributable information.\n\n19. Conflicting Evidence\n\nWhen two sources conflict:\n\nprefer the more structured and directly corresponding source,\navoid combining mutually exclusive values,\ndo not guess which source is correct without evidence.\n\nExample:\n\nraw color = Black\ntitle = Navy Pants\n\nDo NOT automatically output:\n\n["black", "navy"]\n\nPrefer the stronger structured field unless other evidence clearly\nresolves the conflict.\n\nIf the conflict cannot be resolved reliably, use the strongest supported\nvalue or leave the field empty.\n\n20. Missing Evidence\n\nAn empty normalized field is valid.\n\nUse:\n\n[]\n\nfor unresolved list fields.\n\nUse:\n\nnull\n\nfor unresolved nullable scalar fields.\n\nUse:\n\n[]\n\nfor unresolved detail.\n\nDo not fill a field merely because the schema provides one.\n\nExample:\n\nIf there is no explicit season information:\n\n"season": []\n\nis better than guessing:\n\n"season": ["winter"]\n\nfrom wool.\n\n21. Processing Only Requested Fields\n\nOnly normalize fields listed in:\n\nunresolved_fields\n\nExample:\n\n["fit", "material", "season"]\n\nThen only those three fields should be interpreted.\n\nAll other ItemNormalizationResult fields must remain at their schema\ndefaults.\n\nThis prevents the LLM from overwriting or competing with values already\nresolved deterministically.\n\n22. Normalization Metadata\n\nDo NOT return NormalizationMetadata.\n\nThe runtime constructs:\n\ndeterministic_fields\nllm_normalized_fields\nunresolved_fields\n\nafter this normalization result is validated.\n\nYour responsibility is only to return ItemNormalizationResult.\n\nThe runtime will determine:\n\nwhich fields were deterministically populated,\nwhich requested fields received normalized LLM values,\nwhich requested fields remained empty and therefore unresolved.\n23. Example\n\nInput evidence:\n\ntitle:\nMax Mara Women's Black Wool Blend Slim Straight High Rise Dress Pants\n\ncolor:\nBlack\n\nmaterial:\nWool Blend\n\npattern:\nSolid\n\nbrand:\nMax Mara\n\nlocalized_aspects:\n\nFit = Slim\nLeg Style = Straight\nRise = High\nFabric Type = Twill\nClosure = Side Zip\nFeatures = Pockets\nGarment Care = Dry Clean Only\nOccasion = Business, Formal\nSeason = Fall, Winter\n\nIf unresolved_fields contains all normalizable fields,\nvalid normalization includes:\n\n{{\n  "color": ["black"],\n  "size": [],\n  "fit": [\n    "slim",\n    "straight",\n    "high rise"\n  ],\n  "material": [\n    "wool blend",\n    "twill"\n  ],\n  "pattern": [\n    "solid"\n  ],\n  "brand": "Max Mara",\n  "strength": [],\n  "garment_care": [\n    "dry clean only"\n  ],\n  "theme": [],\n  "season": [\n    "fall",\n    "winter"\n  ],\n  "occasion": [\n    "business",\n    "formal"\n  ],\n  "detail": [\n    {{\n      "key": "closure",\n      "values": [\n        "side zip"\n      ]\n    }},\n    {{\n      "key": "features",\n      "values": [\n        "pockets"\n      ]\n    }}\n  ]\n}}\n\nDo not add unsupported values such as:\n\n{{\n  "strength": [\n    "high-quality"\n  ],\n  "theme": [\n    "quiet luxury",\n    "old money"\n  ]\n}}\n24. Final Checklist\n\nBefore returning the result, verify:\n\nEvery normalized value has evidence in the raw item.\nOnly unresolved_fields were interpreted.\nDedicated raw fields were preferred over weaker free-text evidence.\nlocalized_aspects were routed to the appropriate normalized field.\nNo value was invented from product stereotypes or general fashion knowledge.\nNo concept is unnecessarily duplicated across fields.\nExplicit multiple values were preserved when useful.\nUnsupported fields remain empty.\ndetail contains only useful metadata not represented elsewhere.\nNo NormalizationMetadata is returned.\nOutput\n\nReturn exactly one ItemNormalizationResult compatible with the\nrequested schema:\n\ncolor\nsize\nfit\nmaterial\npattern\nbrand\nstrength\ngarment_care\ntheme\nseason\noccasion\ndetail\n\nReturn no additional fields.\n""".strip()

# Source: search.item_normalization.search_item_normalization_v24
def evaluated_mapping_prompt(base_prompt, analysis):
    return base_prompt + '\n\nV21 VALIDATED EVALUATION INPUT:\nIn addition to EBayRawItem, use the validated image/metadata observations below.\nKnown common attributes are already bound by code and are not unresolved fields.\nDo not redo image evaluation or invent new visual observations. User requirements\nand met judgments alone are not evidence of an unobserved product attribute.\nNormalize only requested unresolved fields. Use empty values when unsupported;\nnever output the literal unknown as a product value. Keep size labels separate\nfrom fit/silhouette. Put remaining metadata in detail using English semantic keys;\ndo not duplicate color/size/fit/material/pattern/brand/theme/season/occasion there.\nFor detail conflicts with evaluated observations, code preserves evaluated values.\n' + _json(analysis)
